// Role templates used by the MockProvider. The generated files are real, runnable code;
// they are parameterised by the project and task, and labelled as template output.
import type { Project, Task } from '../../../shared/types';

const oneLine = (s: string) => s.replace(/\s+/g, ' ').trim();

const header = (p0: Project, t: Task, provider = 'mock') => {
  const p = { ...p0, name: oneLine(p0.name), goal: oneLine(p0.goal), constraints: oneLine(p0.constraints) };
  return [
    `// Project: ${p.name}`,
    p.goal ? `// Goal: ${p.goal}` : null,
    p.constraints ? `// Constraints: ${p.constraints}` : null,
    `// Task: ${oneLine(t.title)}`,
    `// Generated by TeamMate Frontend Engineer (provider: ${provider}, role template).`,
  ]
    .filter(Boolean)
    .join('\n');
};

export function bookingModule(p: Project, t: Task): string {
  return `${header(p, t)}
// Pure booking rules. No I/O, so they can be unit-tested with node:test.

export interface Room {
  id: string;
  name: string;
  capacity: number;
}

export interface Booking {
  id?: string;
  roomId: string;
  start: string | Date;
  end: string | Date;
  attendees: number;
}

export interface ValidationResult {
  ok: boolean;
  errors: string[];
}

function toMs(value: string | Date): number {
  return new Date(value).getTime();
}

/** Half-open intervals: a booking ending at 10:00 does not overlap one starting at 10:00. */
export function overlaps(aStart: number, aEnd: number, bStart: number, bEnd: number): boolean {
  return aStart < bEnd && bStart < aEnd;
}

/** Existing bookings for the same room whose time range overlaps the candidate. */
export function findConflicts(candidate: Booking, existing: Booking[]): Booking[] {
  const start = toMs(candidate.start);
  const end = toMs(candidate.end);
  return existing.filter(
    (b) => b.roomId === candidate.roomId && b.id !== candidate.id && overlaps(start, end, toMs(b.start), toMs(b.end)),
  );
}

export function isRoomFree(roomId: string, start: string | Date, end: string | Date, existing: Booking[]): boolean {
  return findConflicts({ roomId, start, end, attendees: 1 }, existing).length === 0;
}

export function validateBooking(candidate: Booking, room: Room, existing: Booking[], now: Date = new Date()): ValidationResult {
  const errors: string[] = [];
  const start = toMs(candidate.start);
  const end = toMs(candidate.end);

  if (Number.isNaN(start) || Number.isNaN(end)) {
    errors.push('Start and end must be valid dates');
    return { ok: false, errors };
  }
  if (end <= start) errors.push('End time must be after start time');
  if (start < now.getTime()) errors.push('Bookings cannot start in the past');
  if (!Number.isInteger(candidate.attendees) || candidate.attendees < 1) errors.push('At least one attendee is required');
  if (candidate.attendees > room.capacity) errors.push('Room "' + room.name + '" holds at most ' + room.capacity + ' people');
  if (candidate.roomId !== room.id) errors.push('Booking is for a different room');
  if (end > start && findConflicts(candidate, existing).length > 0) errors.push('Room is already booked for part of that time');

  return { ok: errors.length === 0, errors };
}
`;
}

export function bookingTests(p: Project, t: Task): string {
  return `${header(p, t)}
// Run with: node --test tests/**/*.test.mjs
import test from 'node:test';
import assert from 'node:assert/strict';
import { validateBooking, findConflicts, isRoomFree } from '../src/booking.ts';

const NOW = new Date('2030-01-01T08:00:00Z');
const room = { id: 'r1', name: 'Study Room A', capacity: 4 };
const existing = [{ id: 'b1', roomId: 'r1', start: '2030-01-01T10:00:00Z', end: '2030-01-01T11:00:00Z', attendees: 2 }];
const at = (start, end, attendees = 2) => ({ roomId: 'r1', start: '2030-01-01T' + start + ':00Z', end: '2030-01-01T' + end + ':00Z', attendees });

test('accepts a valid booking in a free slot', () => {
  const r = validateBooking(at('12:00', '13:00'), room, existing, NOW);
  assert.deepEqual(r, { ok: true, errors: [] });
});

test('rejects a zero-length booking', () => {
  const r = validateBooking(at('12:00', '12:00'), room, existing, NOW);
  assert.equal(r.ok, false);
  assert.ok(r.errors.includes('End time must be after start time'));
});

test('rejects an overlapping booking', () => {
  const r = validateBooking(at('10:30', '11:30'), room, existing, NOW);
  assert.equal(r.ok, false);
  assert.equal(findConflicts(at('10:30', '11:30'), existing).length, 1);
});

test('allows back-to-back bookings', () => {
  assert.equal(validateBooking(at('11:00', '12:00'), room, existing, NOW).ok, true);
  assert.equal(validateBooking(at('09:00', '10:00'), room, existing, NOW).ok, true);
});

test('rejects bookings over room capacity', () => {
  const r = validateBooking(at('12:00', '13:00', 5), room, existing, NOW);
  assert.equal(r.ok, false);
  assert.match(r.errors.join(' '), /at most 4/);
});

test('rejects bookings that start in the past', () => {
  const past = { roomId: 'r1', start: '2029-12-31T10:00:00Z', end: '2029-12-31T11:00:00Z', attendees: 1 };
  const r = validateBooking(past, room, [], NOW);
  assert.ok(r.errors.includes('Bookings cannot start in the past'));
});

test('isRoomFree reflects existing bookings per room', () => {
  assert.equal(isRoomFree('r1', '2030-01-01T10:15:00Z', '2030-01-01T10:45:00Z', existing), false);
  assert.equal(isRoomFree('r2', '2030-01-01T10:15:00Z', '2030-01-01T10:45:00Z', existing), true);
});
`;
}

export function roomAvailabilityComponent(p: Project, t: Task): string {
  return `${header(p, t)}
import { useMemo, useState } from 'react';
import { isRoomFree, type Booking, type Room } from './booking';

export interface RoomAvailabilityProps {
  rooms: Room[];
  bookings: Booking[];
  loading?: boolean;
  error?: string | null;
  /** Window to check, ISO strings. */
  from: string;
  to: string;
  onBook?: (room: Room) => void;
}

export default function RoomAvailability({ rooms, bookings, loading = false, error = null, from, to, onBook }: RoomAvailabilityProps) {
  const [onlyFree, setOnlyFree] = useState(false);

  const rows = useMemo(
    () =>
      rooms
        .map((room) => ({ room, free: isRoomFree(room.id, from, to, bookings) }))
        .filter((r) => !onlyFree || r.free),
    [rooms, bookings, from, to, onlyFree],
  );

  if (loading) {
    return (
      <section aria-busy="true" aria-live="polite" role="status">
        <p>Loading rooms…</p>
      </section>
    );
  }

  if (error) {
    return (
      <section role="alert">
        <p>Could not load rooms: {error}</p>
      </section>
    );
  }

  return (
    <section aria-labelledby="room-availability-title">
      <header>
        <h2 id="room-availability-title">Room availability</h2>
        <label>
          <input type="checkbox" checked={onlyFree} onChange={(e) => setOnlyFree(e.target.checked)} /> Only show free rooms
        </label>
      </header>

      {rows.length === 0 ? (
        <p role="status" aria-live="polite">
          No rooms match. Try another time or turn off the filter.
        </p>
      ) : (
        <ul aria-label="Rooms">
          {rows.map(({ room, free }) => (
            <li key={room.id}>
              <span>{room.name}</span> <span>({room.capacity} seats)</span>{' '}
              <strong aria-label={free ? 'Available' : 'Booked'}>{free ? 'Free' : 'Booked'}</strong>
              <button type="button" disabled={!free} aria-disabled={!free} onClick={() => onBook?.(room)}>
                Book {room.name}
              </button>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}
`;
}

export function mockNote(p: Project, t: Task, roleTitle: string, responsibilities: string[]): string {
  return `# ${t.title}

> **Mock output.** Produced by the ${roleTitle} role template (provider: mock). No model wrote this note;
> it records the task and the checklist this role would work through.

- **Project:** ${p.name}
- **Goal:** ${p.goal || '(not set)'}
- **Constraints:** ${p.constraints || '(none)'}

## Task
${t.description}

## Checklist for this role
${responsibilities.map((r) => `- [ ] ${r}`).join('\n')}
`;
}
